import java.util.Scanner;
import java.util.LinkedList;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        sc.close();

        boolean[] painted = new boolean[n];
        painted[0] = true;

        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);

        while (!queue.isEmpty()) {
            int i = queue.poll();

            for (int x = 1; i + a[i] * x < n; x++) {
                int nextIndex = i + a[i] * x;
                if (!painted[nextIndex]) {
                    painted[nextIndex] = true;
                    queue.add(nextIndex);
                }
            }
        }

        int count = 0;
        for (boolean isPainted : painted) {
            if (isPainted) {
                count++;
            }
        }

        int mod = 998244353;
        System.out.println(count % mod);
    }
}
